  1→// Turbopuffer vector search client for checkpoints
  2→// Uses OpenAI embeddings (text-embedding-3-small) to embed the query,
  3→// then searches Turbopuffer by cosine similarity.
  4→// TODO: add BM25 full-text search as a follow-up once schema is configured.
  5→
  6→const EMBEDDING_MODEL = "text-embedding-3-small";
  7→const EMBEDDING_DIMENSIONS = 1536;
  8→const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
  9→const MAX_ATTRIBUTE_BYTES = 3800; // Turbopuffer limit is 4096, leave headroom
 10→
 11→export interface TurbopufferSearchResult {
 12→  checkpoint_id: string;
 13→}
 14→
 15→interface TurbopufferQueryRow {
 16→  id: number;
 17→  dist: number;
 18→  attributes: {
 19→    checkpoint_id?: string;
 20→  };
 21→}
 22→
 23→type TurbopufferQueryResponse = TurbopufferQueryRow[];
 24→
 25→function truncateToBytes(str: string | null, maxBytes: number): string | null {
 26→  if (str === null) return null;
 27→  if (str.length <= maxBytes) return str;
 28→  const encoder = new TextEncoder();
 29→  const encoded = encoder.encode(str);
 30→  if (encoded.length <= maxBytes) return str;
 31→  const truncated = encoded.slice(0, maxBytes);
 32→  const decoder = new TextDecoder();
 33→  return decoder.decode(truncated);
 34→}
 35→
 36→function buildSearchText(checkpoint: {
 37→  prompt: string | null;
 38→  commit_message: string | null;
 39→  files_touched: string[] | null;
 40→}): string {
 41→  const parts: string[] = [];
 42→  if (checkpoint.prompt) {
 43→    parts.push(`Prompt: ${checkpoint.prompt}`);
 44→  }
 45→  if (checkpoint.commit_message) {
 46→    parts.push(`Commit: ${checkpoint.commit_message}`);
 47→  }
 48→  if (checkpoint.files_touched) {
 49→    parts.push(`Files: ${checkpoint.files_touched.join(", ")}`);
 50→  }
 51→  return parts.join("\n");
 52→}
 53→
 54→// Hash checkpoint_id to a deterministic numeric ID for Turbopuffer
 55→// Uses FNV-1a 32-bit hash for fast, well-distributed IDs
 56→function hashToNumericId(checkpointId: string): number {
 57→  let hash = 0x811c9dc5; // FNV offset basis
 58→  for (let i = 0; i < checkpointId.length; i++) {
 59→    hash ^= checkpointId.charCodeAt(i);
 60→    hash = Math.imul(hash, 0x01000193); // FNV prime
 61→  }
 62→  return hash >>> 0; // unsigned 32-bit
 63→}
 64→
 65→async function embedTexts(
 66→  openaiApiKey: string,
 67→  texts: string[],
 68→): Promise<number[][]> {
 69→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
 70→    method: "POST",
 71→    headers: {
 72→      Authorization: `Bearer ${openaiApiKey}`,
 73→      "Content-Type": "application/json",
 74→    },
 75→    body: JSON.stringify({
 76→      model: EMBEDDING_MODEL,
 77→      input: texts,
 78→      dimensions: EMBEDDING_DIMENSIONS,
 79→    }),
 80→  });
 81→
 82→  if (!resp.ok) {
 83→    const err = await resp.text().catch(() => "");
 84→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
 85→  }
 86→
 87→  const result = (await resp.json()) as {
 88→    data: Array<{ index: number; embedding: number[] }>;
 89→  };
 90→  return result.data
 91→    .sort((a, b) => a.index - b.index)
 92→    .map((item) => item.embedding);
 93→}
 94→
 95→async function embedQuery(openaiApiKey: string, text: string): Promise<number[]> {
 96→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
 97→    method: "POST",
 98→    headers: {
 99→      Authorization: `Bearer ${openaiApiKey}`,
100→      "Content-Type": "application/json",
101→    },
102→    body: JSON.stringify({
103→      model: EMBEDDING_MODEL,
104→      input: text,
105→      dimensions: EMBEDDING_DIMENSIONS,
106→    }),
107→  });
108→
109→  if (!resp.ok) {
110→    const err = await resp.text().catch(() => "");
111→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
112→  }
113→
114→  const result = (await resp.json()) as { data: Array<{ embedding: number[] }> };
115→  return result.data[0].embedding;
116→}
