118→export async function searchCheckpoints(
119→  turbopufferApiKey: string,
120→  openaiApiKey: string,
121→  repoId: string,
122→  query: string,
123→  filters?: { branch?: string },
124→  limit: number = 50,
125→): Promise<TurbopufferSearchResult[]> {
126→  // 1. Embed the query
127→  const vector = await embedQuery(openaiApiKey, query);
128→
129→  // 2. Query Turbopuffer
130→  // TODO: use repoId dynamically once backfill runs per-environment
131→  const namespace = `checkpoints-5be1c302-97d2-4cf4-8436-b001efe227e0`;
132→  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
133→
134→  const body: Record<string, unknown> = {
135→    vector,
136→    top_k: limit,
137→    distance_metric: "cosine_distance",
138→    include_attributes: ["checkpoint_id"],
139→  };
140→
141→  if (filters?.branch) {
142→    body.filters = {
143→      branch: [["Eq", filters.branch]],
144→    };
145→  }
146→
147→  const resp = await fetch(url, {
148→    method: "POST",
149→    headers: {
150→      Authorization: `Bearer ${turbopufferApiKey}`,
151→      "Content-Type": "application/json",
152→    },
153→    body: JSON.stringify(body),
154→  });
155→
156→  if (!resp.ok) {
157→    const text = await resp.text().catch(() => "");
158→    throw new Error(`Turbopuffer query failed (${resp.status}): ${text}`);
159→  }
160→
161→  const result = (await resp.json()) as TurbopufferQueryResponse;
162→
163→  // Deduplicate checkpoint IDs (multiple vectors may map to the same checkpoint)
164→  const seen = new Set<string>();
165→  const results: TurbopufferSearchResult[] = [];
166→
167→  for (const row of result) {
168→    const id = row.attributes?.checkpoint_id;
169→    if (id && !seen.has(id)) {
170→      seen.add(id);
171→      results.push({ checkpoint_id: id });
172→    }
173→  }
174→
175→  return results;
176→}
