  1→/**
  2→ * Backfill script: Index checkpoints into Turbopuffer for full-text + semantic search.
  3→ *
  4→ * Usage:
  5→ *   npx tsx scripts/backfill-search.ts [options]
  6→ *
  7→ * Options:
  8→ *   --repo <full_name>     Only backfill a specific repo (e.g., "entireio/cli")
  9→ *   --with-transcripts     Fetch transcript excerpts from GitHub (slower, needs GITHUB_TOKEN)
 10→ *   --dry-run              Show what would be indexed without writing to Turbopuffer
 11→ *   --limit <n>            Max checkpoints per repo (for testing)
 12→ *
 13→ * Environment:
 14→ *   DATABASE_URL           MySQL connection string (defaults to local Docker MySQL)
 15→ *   TURBOPUFFER_API_KEY    Turbopuffer API key (required unless --dry-run)
 16→ *   OPENAI_API_KEY         OpenAI API key for embeddings (required unless --dry-run)
 17→ *   GITHUB_TOKEN           GitHub PAT with repo read access (required for --with-transcripts)
 18→ */
 19→
 20→import { Kysely, MysqlDialect } from "kysely";
 21→import { createPool } from "mysql2";
 22→import type { DB } from "../db/types";
 23→import { Turbopuffer } from "@turbopuffer/turbopuffer";
 24→import type { Vector } from "@turbopuffer/turbopuffer";
 25→import OpenAI from "openai";
 26→import { getParserForAgent } from "../src/lib/transcript-parsers/registry";
 27→
 28→// --- Config ---
 29→
 30→const EMBEDDING_MODEL = "text-embedding-3-small";
 31→const EMBEDDING_DIMENSIONS = 1536;
 32→const CHUNK_SIZE = 50; // process checkpoints in chunks of 50 (fetch transcripts + embed + upsert per chunk)
 33→const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
 34→const GITHUB_API = "https://api.github.com";
 35→const TRANSCRIPT_DELAY_MS = 100; // delay between GitHub API calls to avoid rate limiting
 36→const MAX_TRANSCRIPT_CHARS = 2000;
 37→const MAX_ATTRIBUTE_BYTES = 3800; // Turbopuffer limit is 4096, leave headroom
 38→const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
 39→const MAX_RETRIES = 3;
 40→const RETRY_BASE_DELAY_MS = 1000;
 41→
 42→// --- CLI Argument Parsing ---
 43→
 44→interface CliOptions {
 45→  repo: string | null;
 46→  withTranscripts: boolean;
 47→  dryRun: boolean;
 48→  limit: number | null;
 49→}
 50→
 51→function parseArgs(): CliOptions {
 52→  const args = process.argv.slice(2);
 53→  const options: CliOptions = {
 54→    repo: null,
 55→    withTranscripts: false,
 56→    dryRun: false,
 57→    limit: null,
 58→  };
 59→
 60→  for (let i = 0; i < args.length; i++) {
 61→    switch (args[i]) {
 62→      case "--repo":
 63→        options.repo = args[++i];
 64→        if (!options.repo) {
 65→          console.error("Error: --repo requires a value (e.g., 'entireio/cli')");
 66→          process.exit(1);
 67→        }
 68→        break;
 69→      case "--with-transcripts":
 70→        options.withTranscripts = true;
 71→        break;
 72→      case "--dry-run":
 73→        options.dryRun = true;
 74→        break;
 75→      case "--limit":
 76→        options.limit = parseInt(args[++i], 10);
 77→        if (isNaN(options.limit) || options.limit <= 0) {
 78→          console.error("Error: --limit requires a positive integer");
 79→          process.exit(1);
 80→        }
 81→        break;
 82→      default:
 83→        console.error(`Unknown option: ${args[i]}`);
 84→        console.error("Usage: npx tsx scripts/backfill-search.ts [--repo <name>] [--with-transcripts] [--dry-run] [--limit <n>]");
 85→        process.exit(1);
 86→    }
 87→  }
 88→
 89→  return options;
 90→}
 91→
 92→// --- Database Setup ---
 93→
 94→function createDb(): Kysely<DB> {
 95→  const url = process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
 96→  const parsed = new URL(url);
 97→  const isLocalhost = parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1";
 98→
 99→  return new Kysely<DB>({
100→    dialect: new MysqlDialect({
101→      pool: createPool({
102→        host: parsed.hostname,
103→        port: Number(parsed.port) || 3306,
104→        user: decodeURIComponent(parsed.username),
105→        password: decodeURIComponent(parsed.password),
106→        database: parsed.pathname.replace("/", ""),
107→        ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
108→      }),
109→    }),
110→  });
111→}
