113→// --- Text Construction ---
114→
115→function buildSearchText(
116→  checkpoint: CheckpointRow,
117→  transcriptExcerpt?: string,
118→): string {
119→  const parts: string[] = [];
120→
121→  if (checkpoint.prompt) {
122→    parts.push(`Prompt: ${checkpoint.prompt}`);
123→  }
124→  if (checkpoint.commit_message) {
125→    parts.push(`Commit: ${checkpoint.commit_message}`);
126→  }
127→  if (checkpoint.files_touched_str) {
128→    parts.push(`Files: ${checkpoint.files_touched_str}`);
129→  }
130→  if (transcriptExcerpt) {
131→    parts.push(`Transcript: ${transcriptExcerpt}`);
132→  }
133→
134→  return parts.join("\n");
135→}
