137→// --- Embedding Generation ---
138→
139→async function generateEmbeddings(
140→  openai: OpenAI,
141→  texts: string[],
142→): Promise<number[][]> {
143→  const response = await openai.embeddings.create({
144→    model: EMBEDDING_MODEL,
145→    input: texts,
146→    dimensions: EMBEDDING_DIMENSIONS,
147→  });
148→
149→  // Sort by index to maintain order
150→  return response.data
151→    .sort((a, b) => a.index - b.index)
152→    .map((item) => item.embedding);
153→}
154→
155→// --- Attribute Truncation ---
156→
157→function truncateToBytes(str: string | null, maxBytes: number): string | null {
158→  if (str === null) return null;
159→  // Fast path: ASCII strings where 1 char = 1 byte
160→  if (str.length <= maxBytes) return str;
161→  // Truncate by encoding to bytes
162→  const encoder = new TextEncoder();
163→  const encoded = encoder.encode(str);
164→  if (encoded.length <= maxBytes) return str;
165→  // Find the last valid UTF-8 boundary within maxBytes
166→  const truncated = encoded.slice(0, maxBytes);
167→  const decoder = new TextDecoder("utf-8", { fatal: false });
168→  return decoder.decode(truncated);
169→}
170→
171→// --- Fetch with Retry ---
172→
173→async function fetchWithRetry(
174→  url: string,
175→  options: RequestInit,
176→): Promise<Response> {
177→  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
178→    try {
179→      const response = await fetch(url, options);
180→      // Retry on transient server errors and rate limits
181→      if (response.status >= 500 || response.status === 429) {
182→        if (attempt < MAX_RETRIES - 1) {
183→          const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
184→          await sleep(delay);
185→          continue;
186→        }
187→      }
188→      return response;
189→    } catch (err) {
190→      if (attempt < MAX_RETRIES - 1) {
191→        const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
192→        await sleep(delay);
193→        continue;
194→      }
195→      throw err;
196→    }
197→  }
198→  throw new Error("fetchWithRetry: exhausted retries");
199→}
