268→// --- Types ---
269→
270→interface CheckpointRow {
271→  checkpoint_id: string;
272→  branch: string;
273→  agent: string;
274→  commit_author_username: string | null;
275→  created_at: string | null;
276→  commit_sha: string | null;
277→  commit_message: string | null;
278→  prompt: string | null;
279→  files_touched_str: string | null;
280→}
281→
282→interface RepoRow {
283→  id: string;
284→  full_name: string;
285→  checkpoint_count: number;
286→}
