358→async function processRepo(
359→  db: Kysely<DB>,
360→  tpuf: Turbopuffer,
361→  openai: OpenAI,
362→  repo: RepoRow,
363→  options: CliOptions,
364→): Promise<{ indexed: number; skipped: number }> {
365→  const start = Date.now();
366→  const total = repo.checkpoint_count;
367→  console.log(`\n--- ${repo.full_name} (${total} checkpoints) ---`);
368→
369→  const checkpoints = await fetchCheckpointsForRepo(db, repo.id, options.limit);
370→  if (checkpoints.length === 0) {
371→    console.log(`  No checkpoint commits found, skipping.`);
372→    return { indexed: 0, skipped: 0 };
373→  }
374→
375→  console.log(`  Fetched ${checkpoints.length} checkpoint rows from DB.`);
376→
377→  const githubToken = process.env.GITHUB_TOKEN;
378→  const ns = tpuf.namespace(`checkpoints-${repo.id}`);
379→  let totalIndexed = 0;
380→  let totalSkipped = 0;
381→  let totalTranscripts = 0;
382→
383→  // Process in chunks: for each chunk, fetch transcripts -> build text -> embed -> upsert
384→  const numChunks = Math.ceil(checkpoints.length / CHUNK_SIZE);
385→
386→  for (let chunkIdx = 0; chunkIdx < numChunks; chunkIdx++) {
387→    const chunkStart = chunkIdx * CHUNK_SIZE;
388→    const chunkEnd = Math.min(chunkStart + CHUNK_SIZE, checkpoints.length);
389→    const chunk = checkpoints.slice(chunkStart, chunkEnd);
390→    const chunkNum = chunkIdx + 1;
391→    const elapsed = formatElapsed(Date.now() - start);
392→
393→    console.log(`  [${chunkNum}/${numChunks}] Processing checkpoints ${chunkStart + 1}-${chunkEnd} of ${checkpoints.length} (${elapsed})`);
394→
395→    // 1. Fetch transcripts for this chunk
396→    const transcripts: (string | undefined)[] = [];
397→    if (options.withTranscripts && githubToken) {
398→      let fetched = 0;
399→      let found = 0;
400→      for (const cp of chunk) {
401→        const excerpt = await fetchTranscriptExcerpt(repo.full_name, cp.checkpoint_id, cp.agent, githubToken);
402→        transcripts.push(excerpt ?? undefined);
403→        fetched++;
404→        if (excerpt) found++;
405→        if (fetched < chunk.length) {
406→          await sleep(TRANSCRIPT_DELAY_MS);
407→        }
408→      }
409→      totalTranscripts += found;
410→      console.log(`    Transcripts: ${found}/${chunk.length} found`);
411→    } else {
412→      chunk.forEach(() => transcripts.push(undefined));
413→    }
414→
415→    // 2. Build search text for each checkpoint
416→    const texts: string[] = [];
417→    const validIndices: number[] = []; // indices within this chunk that have non-empty text
418→    let chunkSkipped = 0;
419→
420→    for (let i = 0; i < chunk.length; i++) {
421→      const text = buildSearchText(chunk[i], transcripts[i]);
422→      if (!text.trim()) {
423→        chunkSkipped++;
424→        continue;
425→      }
426→      texts.push(text);
427→      validIndices.push(i);
428→    }
429→
430→    totalSkipped += chunkSkipped;
431→
432→    if (texts.length === 0) {
433→      console.log(`    All empty, skipped.`);
434→      continue;
435→    }
436→
437→    if (options.dryRun) {
438→      console.log(`    [DRY RUN] Would index ${texts.length} (${chunkSkipped} skipped)`);
439→      totalIndexed += texts.length;
440→      continue;
441→    }
442→
443→    // 3. Truncate texts to stay under embedding model token limit
444→    const embeddingTexts = texts.map((t) => t.slice(0, MAX_EMBEDDING_CHARS));
445→
446→    // 4. Generate embeddings
447→    let embeddings: number[][];
448→    try {
449→      embeddings = await generateEmbeddings(openai, embeddingTexts);
450→    } catch (err) {
451→      const msg = err instanceof Error ? err.message : String(err);
452→      console.error(`    Embedding failed for chunk ${chunkNum}: ${msg.slice(0, 200)}`);
453→      console.error(`    Skipping chunk, continuing...`);
454→      totalSkipped += texts.length;
455→      continue;
456→    }
457→    console.log(`    Embedded ${texts.length} checkpoints`);
458→
459→    // 5. Upsert to Turbopuffer
460→    const vectors: Vector[] = validIndices.map((localIdx, j) => {
461→      const cp = chunk[localIdx];
462→      const globalId = chunkStart + localIdx + 1; // unique ID across all chunks
463→      return {
464→        id: globalId,
465→        vector: embeddings[j],
466→        attributes: {
467→          checkpoint_id: cp.checkpoint_id,
468→          branch: cp.branch,
469→          agent: cp.agent,
470→          author: cp.commit_author_username,
471→          created_at: cp.created_at,
472→          commit_sha: cp.commit_sha,
473→          commit_message: truncateToBytes(cp.commit_message, MAX_ATTRIBUTE_BYTES),
474→          prompt: truncateToBytes(cp.prompt, MAX_ATTRIBUTE_BYTES),
475→          files_touched: truncateToBytes(cp.files_touched_str, MAX_ATTRIBUTE_BYTES),
476→          text: truncateToBytes(texts[j], MAX_ATTRIBUTE_BYTES),
477→        },
478→      };
479→    });
480→
481→    try {
482→      await ns.upsert({
483→        vectors,
484→        distance_metric: "cosine_distance",
485→      });
486→      totalIndexed += texts.length;
487→      console.log(`    Upserted ${texts.length} to Turbopuffer (${totalIndexed} total)`);
488→    } catch (err) {
489→      const msg = err instanceof Error ? err.message : String(err);
490→      console.error(`    Upsert failed for chunk ${chunkNum}: ${msg.slice(0, 200)}`);
491→      console.error(`    Skipping chunk, continuing...`);
492→      totalSkipped += texts.length;
493→    }
494→  }
495→
496→  const elapsed = formatElapsed(Date.now() - start);
497→  console.log(`  Done: ${totalIndexed} indexed, ${totalSkipped} skipped, ${totalTranscripts} transcripts (${elapsed})`);
498→
499→  return { indexed: totalIndexed, skipped: totalSkipped };
500→}
