  1→/**
  2→ * Test script: Exercises the search index pipeline locally.
  3→ *
  4→ * Usage:
  5→ *   npx tsx scripts/test-search-index.ts [--repo <full_name>] [--limit <n>] [--dry-run]
  6→ *
  7→ * Environment:
  8→ *   DATABASE_URL           MySQL connection string (defaults to local Docker MySQL)
  9→ *   TURBOPUFFER_API_KEY    Turbopuffer API key (required unless --dry-run)
 10→ *   OPENAI_API_KEY         OpenAI API key for embeddings (required unless --dry-run)
 11→ */
 12→
 13→import { Kysely, MysqlDialect } from "kysely";
 14→import { createPool } from "mysql2";
 15→import type { DB } from "../db/types";
 16→
 17→// --- Config ---
 18→
 19→const EMBEDDING_MODEL = "text-embedding-3-small";
 20→const EMBEDDING_DIMENSIONS = 1536;
 21→const MAX_EMBEDDING_CHARS = 25000;
 22→const MAX_ATTRIBUTE_BYTES = 3800;
 23→
 24→// --- CLI ---
 25→
 26→interface CliOptions {
 27→  repo: string | null;
 28→  limit: number;
 29→  dryRun: boolean;
 30→}
 31→
 32→function parseArgs(): CliOptions {
 33→  const args = process.argv.slice(2);
 34→  const options: CliOptions = { repo: null, limit: 5, dryRun: false };
 35→
 36→  for (let i = 0; i < args.length; i++) {
 37→    switch (args[i]) {
 38→      case "--repo":
 39→        options.repo = args[++i];
 40→        break;
 41→      case "--limit":
 42→        options.limit = parseInt(args[++i], 10);
 43→        break;
 44→      case "--dry-run":
 45→        options.dryRun = true;
 46→        break;
 47→      default:
 48→        console.error(`Unknown option: ${args[i]}`);
 49→        process.exit(1);
 50→    }
 51→  }
 52→  return options;
 53→}
 54→
 55→// --- Database ---
 56→
 57→function createDb(): Kysely<DB> {
 58→  const url =
 59→    process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
 60→  const parsed = new URL(url);
 61→  return new Kysely<DB>({
 62→    dialect: new MysqlDialect({
 63→      pool: createPool({
 64→        host: parsed.hostname,
 65→        port: Number(parsed.port) || 3306,
 66→        user: decodeURIComponent(parsed.username),
 67→        password: decodeURIComponent(parsed.password),
 68→        database: parsed.pathname.replace("/", ""),
 69→      }),
 70→    }),
 71→  });
 72→}
 73→
 74→// --- Helpers (mirroring turbopuffer.ts) ---
 75→
 76→function truncateToBytes(str: string | null, maxBytes: number): string | null {
 77→  if (str === null) return null;
 78→  if (str.length <= maxBytes) return str;
 79→  const encoder = new TextEncoder();
 80→  const encoded = encoder.encode(str);
 81→  if (encoded.length <= maxBytes) return str;
 82→  const truncated = encoded.slice(0, maxBytes);
 83→  return new TextDecoder().decode(truncated);
 84→}
 85→
 86→function buildSearchText(checkpoint: {
 87→  prompt: string | null;
 88→  commit_message: string | null;
 89→  files_touched_str: string | null;
 90→}): string {
 91→  const parts: string[] = [];
 92→  if (checkpoint.prompt) parts.push(`Prompt: ${checkpoint.prompt}`);
 93→  if (checkpoint.commit_message)
 94→    parts.push(`Commit: ${checkpoint.commit_message}`);
 95→  if (checkpoint.files_touched_str)
 96→    parts.push(`Files: ${checkpoint.files_touched_str}`);
 97→  return parts.join("\n");
 98→}
 99→
100→function hashToNumericId(checkpointId: string): number {
101→  let hash = 0x811c9dc5;
102→  for (let i = 0; i < checkpointId.length; i++) {
103→    hash ^= checkpointId.charCodeAt(i);
104→    hash = Math.imul(hash, 0x01000193);
105→  }
106→  return hash >>> 0;
107→}
