130→  if (options.repo) console.log(`  repo:    ${options.repo}`);
131→  console.log();
132→
133→  // Step 1: Fetch checkpoints from DB
134→  const db = createDb();
135→
136→  let repoQuery = db
137→    .selectFrom("repos")
