export async function searchCheckpoints(
  turbopufferApiKey: string,
  openaiApiKey: string,
  repoId: string,
  query: string,
  filters?: { branch?: string },
  limit: number = 50,
): Promise<TurbopufferSearchResult[]> {
  // 1. Embed the query
  const vector = await embedQuery(openaiApiKey, query);

  // 2. Query Turbopuffer
  // TODO: use repoId dynamically once backfill runs per-environment
  const namespace = `checkpoints-5be1c302-97d2-4cf4-8436-b001efe227e0`;
  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;

  const body: Record<string, unknown> = {
    vector,
    top_k: limit,
    distance_metric: "cosine_distance",
    include_attributes: ["checkpoint_id"],
  };

  if (filters?.branch) {
    body.filters = {
      branch: [["Eq", filters.branch]],
    };
  }

  const resp = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${turbopufferApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });

  if (!resp.ok) {
    const text = await resp.text().catch(() => "");
    throw new Error(`Turbopuffer query failed (${resp.status}): ${text}`);
  }

  const result = (await resp.json()) as TurbopufferQueryResponse;

  // Deduplicate checkpoint IDs (multiple vectors may map to the same checkpoint)
  const seen = new Set<string>();
  const results: TurbopufferSearchResult[] = [];

  for (const row of result) {
    const id = row.attributes?.checkpoint_id;
    if (id && !seen.has(id)) {
      seen.add(id);
      results.push({ checkpoint_id: id });
    }
  }

  return results;
}

