// RRF constant — standard value that prevents top-ranked items from dominating
const RRF_K = 60;

export async function searchCheckpoints(
  turbopufferApiKey: string,
  openaiApiKey: string,
  repoId: string,
  query: string,
  filters?: { branch?: string },
  limit: number = 50,
): Promise<TurbopufferSearchResult[]> {
  // TODO: use repoId dynamically once backfill runs per-environment
  const namespace = `checkpoints-5be1c302-97d2-4cf4-8436-b001efe227e0`;

  const headers = {
    Authorization: `Bearer ${turbopufferApiKey}`,
    "Content-Type": "application/json",
  };

  const branchFilters = filters?.branch
    ? { branch: [["Eq", filters.branch]] }
    : undefined;

  // Fire vector + BM25 queries in parallel
  const [vectorResults, bm25Results] = await Promise.all([
    // Vector cosine similarity (v1 API)
    (async (): Promise<TurbopufferQueryRow[]> => {
      const vector = await embedQuery(openaiApiKey, query);
      const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
      const body: Record<string, unknown> = {
        vector,
        top_k: limit,
        distance_metric: "cosine_distance",
        include_attributes: ["checkpoint_id"],
      };
      if (branchFilters) body.filters = branchFilters;

      const resp = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
      });
      if (!resp.ok) {
        const text = await resp.text().catch(() => "");
        throw new Error(`Turbopuffer vector query failed (${resp.status}): ${text}`);
      }
      return (await resp.json()) as TurbopufferQueryResponse;
    })(),

    // BM25 full-text search (v2 API)
    (async (): Promise<TurbopufferQueryRow[]> => {
      const url = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`;
      const body: Record<string, unknown> = {
        rank_by: ["text", "BM25", query],
        top_k: limit,
        include_attributes: ["checkpoint_id"],
      };
      if (branchFilters) body.filters = branchFilters;

      const resp = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
      });
      if (!resp.ok) {
        const text = await resp.text().catch(() => "");
        throw new Error(`Turbopuffer BM25 query failed (${resp.status}): ${text}`);
      }
      return (await resp.json()) as TurbopufferQueryResponse;
    })(),
  ]);

  // Merge via Reciprocal Rank Fusion (RRF)
  // score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
  const scores = new Map<string, number>();

  for (let rank = 0; rank < vectorResults.length; rank++) {
    const id = vectorResults[rank].attributes?.checkpoint_id;
    if (id) {
      scores.set(id, (scores.get(id) ?? 0) + 1 / (RRF_K + rank + 1));
    }
  }

  for (let rank = 0; rank < bm25Results.length; rank++) {
    const id = bm25Results[rank].attributes?.checkpoint_id;
    if (id) {
      scores.set(id, (scores.get(id) ?? 0) + 1 / (RRF_K + rank + 1));
    }
  }

  // Sort by RRF score descending, take top `limit`
  const sorted = [...scores.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit);

  return sorted.map(([checkpoint_id]) => ({ checkpoint_id }));
}

