  }),
});

if (searchResp.ok) {
  const searchResult = (await searchResp.json()) as Array<{
    id: number;
    dist: number;
    attributes: Record<string, string>;
  }>;
  console.log(`  Vector results (${searchResult.length}):`);
  for (const row of searchResult) {
    console.log(
      `    id=${row.id} dist=${row.dist.toFixed(4)} checkpoint=${row.attributes?.checkpoint_id} prompt="${(row.attributes?.prompt ?? "").slice(0, 60)}..."`,
    );
  }
} else {
  const errText = await searchResp.text();
  console.error(`  Vector search failed (${searchResp.status}): ${errText}`);
}

// Step 7: Verify BM25 full-text search
console.log(`\n[7/8] Verifying BM25 full-text search...`);
// Use a keyword from the first checkpoint's text for an exact match test
const firstCpText = textsWithCheckpoints[0].text;
const bm25Query = firstCpText.split(/\s+/).slice(0, 5).join(" ");
console.log(`  BM25 query: "${bm25Query}"`);

const bm25Url = `https://api.turbopuffer.com/v2/namespaces/${encodeURIComponent(namespace)}/query`;
const bm25Resp = await fetch(bm25Url, {
  method: "POST",
  headers: {
    Authorization: `Bearer ${turbopufferApiKey}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    rank_by: ["text", "BM25", bm25Query],
    top_k: 3,
    include_attributes: ["checkpoint_id", "prompt"],
  }),
});

if (bm25Resp.ok) {
  const bm25Result = (await bm25Resp.json()) as Array<{
    id: number;
    dist: number;
    attributes: Record<string, string>;
  }>;
  console.log(`  BM25 results (${bm25Result.length}):`);
  for (const row of bm25Result) {
    console.log(
      `    id=${row.id} dist=${row.dist.toFixed(4)} checkpoint=${row.attributes?.checkpoint_id} prompt="${(row.attributes?.prompt ?? "").slice(0, 60)}..."`,
    );
  }
} else {
  const errText = await bm25Resp.text();
  console.error(`  BM25 search failed (${bm25Resp.status}): ${errText}`);
}

// Step 8: Verify hybrid search (RRF fusion of vector + BM25)
console.log(`\n[8/8] Verifying hybrid search (vector + BM25 via RRF)...`);
console.log(`  Query: "${bm25Query}"`);

// Fire both queries in parallel
const [hybridVectorResp, hybridBm25Resp] = await Promise.all([
  fetch(searchUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${turbopufferApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      vector: queryVector,
      top_k: 3,
      distance_metric: "cosine_distance",
      include_attributes: ["checkpoint_id", "prompt"],
    }),
  }),
  fetch(bm25Url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${turbopufferApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      rank_by: ["text", "BM25", bm25Query],
      top_k: 3,
      include_attributes: ["checkpoint_id", "prompt"],
    }),
  }),
]);

if (hybridVectorResp.ok && hybridBm25Resp.ok) {
  const vectorRows = (await hybridVectorResp.json()) as Array<{
    id: number;
    attributes: Record<string, string>;
  }>;
  const bm25Rows = (await hybridBm25Resp.json()) as Array<{
    id: number;
    attributes: Record<string, string>;
  }>;

  // RRF merge (k=60)
  const RRF_K = 60;
  const scores = new Map<string, { score: number; prompt: string }>();
  for (let rank = 0; rank < vectorRows.length; rank++) {
    const cpId = vectorRows[rank].attributes?.checkpoint_id;
    if (cpId) {
      const existing = scores.get(cpId);
      scores.set(cpId, {
        score: (existing?.score ?? 0) + 1 / (RRF_K + rank + 1),
        prompt: existing?.prompt ?? vectorRows[rank].attributes?.prompt ?? "",
      });
    }
  }
  for (let rank = 0; rank < bm25Rows.length; rank++) {
    const cpId = bm25Rows[rank].attributes?.checkpoint_id;
    if (cpId) {
      const existing = scores.get(cpId);
      scores.set(cpId, {
        score: (existing?.score ?? 0) + 1 / (RRF_K + rank + 1),
        prompt: existing?.prompt ?? bm25Rows[rank].attributes?.prompt ?? "",
      });
    }
  }

  const sorted = [...scores.entries()].sort((a, b) => b[1].score - a[1].score);
  console.log(`  Hybrid results (${sorted.length}):`);
  for (const [cpId, { score, prompt }] of sorted) {
    console.log(
      `    checkpoint=${cpId} rrf_score=${score.toFixed(6)} prompt="${(prompt ?? "").slice(0, 60)}..."`,
    );
  }
} else {
  console.error(`  Hybrid search failed — vector: ${hybridVectorResp.status}, bm25: ${hybridBm25Resp.status}`);
}

console.log("\nDone!");

