171→        rank_by: ["text", "BM25", query],
172→        top_k: limit,
173→        include_attributes: ["checkpoint_id"],
174→      };
175→      if (branchFilters) body.filters = branchFilters;
176→
177→      const resp = await fetch(url, {
178→        method: "POST",
179→        headers,
180→        body: JSON.stringify(body),
181→      });
182→      if (!resp.ok) {
183→        const text = await resp.text().catch(() => "");
184→        throw new Error(`Turbopuffer BM25 query failed (${resp.status}): ${text}`);
185→      }
186→      return (await resp.json()) as TurbopufferQueryResponse;
187→    })(),
188→  ]);
189→
190→  // Merge via Reciprocal Rank Fusion (RRF)
191→  // score(doc) = 1/(k + rank_vector) + 1/(k + rank_bm25)
192→  const scores = new Map<string, number>();
193→
194→  for (let rank = 0; rank < vectorResults.length; rank++) {
195→    const id = vectorResults[rank].attributes?.checkpoint_id;
196→    if (id) {
197→      scores.set(id, (scores.get(id) ?? 0) + 1 / (RRF_K + rank + 1));
198→    }
199→  }
200→
201→  for (let rank = 0; rank < bm25Results.length; rank++) {
202→    const id = bm25Results[rank].attributes?.checkpoint_id;
203→    if (id) {
204→      scores.set(id, (scores.get(id) ?? 0) + 1 / (RRF_K + rank + 1));
205→    }
206→  }
207→
208→  // Sort by RRF score descending, take top `limit`
209→  const sorted = [...scores.entries()]
210→    .sort((a, b) => b[1] - a[1])
211→    .slice(0, limit);
212→
213→  return sorted.map(([checkpoint_id]) => ({ checkpoint_id }));
214→}
215→
216→// Index checkpoints into Turbopuffer for vector search
217→// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
218→// Returns the number of successfully indexed checkpoints
219→export async function indexCheckpoints(
220→  turbopufferApiKey: string,
221→  openaiApiKey: string,
222→  repoId: string,
223→  checkpoints: Array<{
224→    checkpoint_id: string;
225→    branch: string | null;
226→    agent: string | null;
227→    commit_author_username: string | null;
228→    created_at: string | null;
229→    commit_sha: string | null;
230→    commit_message: string | null;
231→    prompt: string | null;
232→    files_touched: string[] | null;
233→  }>,
234→): Promise<number> {
235→  // Build search text and filter out empty entries
236→  const validCheckpoints: Array<{
237→    checkpoint: (typeof checkpoints)[number];
238→    text: string;
239→  }> = [];
240→
241→  for (const cp of checkpoints) {
242→    const text = buildSearchText(cp);
243→    if (text.trim()) {
244→      validCheckpoints.push({ checkpoint: cp, text });
245→    }
246→  }
247→
248→  if (validCheckpoints.length === 0) {
249→    return 0;
250→  }
251→
252→  // Truncate texts for embedding model token limit
253→  const embeddingTexts = validCheckpoints.map((v) =>
254→    v.text.slice(0, MAX_EMBEDDING_CHARS),
255→  );
256→
257→  // Embed all texts in one batch call
258→  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);
259→
260→  // Build upsert payload (row-based format for Turbopuffer v1 API)
261→  const upserts = validCheckpoints.map(({ checkpoint, text }, i) => {
262→    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;
263→    return {
264→      id: hashToNumericId(checkpoint.checkpoint_id),
265→      vector: embeddings[i],
266→      attributes: {
267→        checkpoint_id: checkpoint.checkpoint_id,
268→        branch: checkpoint.branch,
269→        agent: checkpoint.agent,
270→        author: checkpoint.commit_author_username,
271→        created_at: checkpoint.created_at,
272→        commit_sha: checkpoint.commit_sha,
273→        commit_message: truncateToBytes(
274→          checkpoint.commit_message,
275→          MAX_ATTRIBUTE_BYTES,
276→        ),
277→        prompt: truncateToBytes(checkpoint.prompt, MAX_ATTRIBUTE_BYTES),
278→        files_touched: truncateToBytes(filesTouchedStr, MAX_ATTRIBUTE_BYTES),
279→        text: truncateToBytes(text, MAX_ATTRIBUTE_BYTES),
280→      },
281→    };
282→  });
283→
284→  // Upsert to Turbopuffer
285→  const namespace = `checkpoints-${repoId}`;
286→  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}`;
287→
288→  const resp = await fetch(url, {
289→    method: "POST",
290→    headers: {
291→      Authorization: `Bearer ${turbopufferApiKey}`,
292→      "Content-Type": "application/json",
293→    },
294→    body: JSON.stringify({
295→      upserts,
296→      distance_metric: "cosine_distance",
297→      schema: {
298→        text: {
299→          type: "string",
300→          full_text_search: {
301→            language: "english",
302→            stemming: true,
303→            remove_stopwords: true,
304→          },
305→        },
306→      },
307→    }),
308→  });
309→
310→  if (!resp.ok) {
311→    const errText = await resp.text().catch(() => "");
312→    throw new Error(`Turbopuffer upsert failed (${resp.status}): ${errText}`);
313→  }
314→
315→  return validCheckpoints.length;
316→}
